import demo from "./demo.jpg"

function assetSrc(asset: string | { src: string }) {
  return typeof asset === "string" ? asset : asset.src
}

/** Demo photo shipped beside the component (`./demo.jpg`). */
export const DEMO_IMAGE = assetSrc(demo)

export {
  ImageCropper,
  type ImageCropperProps,
  type Area,
  type Point,
} from "./image-cropper"
export {
  getCroppedImg,
  getCroppedImgUrl,
  type CropImageOptions,
} from "./lib"

"use client"

import * as React from "react"
import Cropper, {
  type Area,
  type Point,
} from "react-easy-crop"

import { Slider } from "@/components/ui/slider"
import { cn } from "@/lib/utils"

export type ImageCropperProps = {
  /** Image URL or object URL. */
  src: string
  /** Crop aspect ratio. Default `1` (square). Pass `undefined` for free aspect via cropSize. */
  aspect?: number
  cropShape?: "rect" | "round"
  showGrid?: boolean
  zoom?: number
  defaultZoom?: number
  onZoomChange?: (zoom: number) => void
  minZoom?: number
  maxZoom?: number
  rotation?: number
  defaultRotation?: number
  onRotationChange?: (rotation: number) => void
  /** Fires with percent + pixel crop areas when the user finishes a gesture. */
  onCropComplete?: (croppedArea: Area, croppedAreaPixels: Area) => void
  /** Also fires while dragging (more frequent). */
  onCropAreaChange?: (croppedArea: Area, croppedAreaPixels: Area) => void
  showZoomSlider?: boolean
  className?: string
  /** Height of the crop stage. Default `h-72`. */
  stageClassName?: string
  disabled?: boolean
}

function ImageCropper({
  src,
  aspect = 1,
  cropShape = "rect",
  showGrid = true,
  zoom: zoomProp,
  defaultZoom = 1,
  onZoomChange,
  minZoom = 1,
  maxZoom = 3,
  rotation: rotationProp,
  defaultRotation = 0,
  onRotationChange,
  onCropComplete,
  onCropAreaChange,
  showZoomSlider = true,
  className,
  stageClassName,
  disabled = false,
}: ImageCropperProps) {
  const [crop, setCrop] = React.useState<Point>({ x: 0, y: 0 })
  const [uncontrolledZoom, setUncontrolledZoom] = React.useState(defaultZoom)
  const [uncontrolledRotation, setUncontrolledRotation] =
    React.useState(defaultRotation)

  const zoom = zoomProp ?? uncontrolledZoom
  const rotation = rotationProp ?? uncontrolledRotation

  const setZoom = (next: number) => {
    if (zoomProp === undefined) setUncontrolledZoom(next)
    onZoomChange?.(next)
  }

  const setRotation = (next: number) => {
    if (rotationProp === undefined) setUncontrolledRotation(next)
    onRotationChange?.(next)
  }

  return (
    <div
      data-slot="image-cropper"
      data-disabled={disabled ? "" : undefined}
      className={cn("flex w-full flex-col gap-3", className)}
    >
      <div
        className={cn(
          "relative h-72 w-full overflow-hidden rounded-[12px] border border-border/70 bg-muted",
          disabled && "pointer-events-none opacity-50",
          stageClassName
        )}
      >
        <Cropper
          image={src}
          crop={crop}
          zoom={zoom}
          rotation={rotation}
          aspect={aspect}
          minZoom={minZoom}
          maxZoom={maxZoom}
          cropShape={cropShape}
          showGrid={showGrid}
          onCropChange={setCrop}
          onZoomChange={setZoom}
          onRotationChange={setRotation}
          onCropComplete={onCropComplete}
          onCropAreaChange={onCropAreaChange}
          style={{
            containerStyle: { borderRadius: 12 },
          }}
        />
      </div>
      {showZoomSlider ? (
        <div className="flex items-center gap-3 px-0.5">
          <span className="w-10 shrink-0 text-xs text-muted-foreground">
            Zoom
          </span>
          <Slider
            value={[zoom]}
            min={minZoom}
            max={maxZoom}
            step={0.05}
            disabled={disabled}
            onValueChange={(v) => setZoom(v[0] ?? minZoom)}
            aria-label="Zoom"
            className="flex-1"
          />
        </div>
      ) : null}
    </div>
  )
}

export { ImageCropper }
export type { Area, Point }

import type { Area } from "react-easy-crop"

function createImage(url: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const image = new Image()
    image.addEventListener("load", () => resolve(image))
    image.addEventListener("error", (error) => reject(error))
    image.crossOrigin = "anonymous"
    image.src = url
  })
}

function getRadianAngle(degreeValue: number) {
  return (degreeValue * Math.PI) / 180
}

function rotateSize(width: number, height: number, rotation: number) {
  const rotRad = getRadianAngle(rotation)
  return {
    width:
      Math.abs(Math.cos(rotRad) * width) + Math.abs(Math.sin(rotRad) * height),
    height:
      Math.abs(Math.sin(rotRad) * width) + Math.abs(Math.cos(rotRad) * height),
  }
}

export type CropImageOptions = {
  rotation?: number
  flip?: { horizontal?: boolean; vertical?: boolean }
  mimeType?: string
  quality?: number
}

/**
 * Crop `src` using pixel area from `react-easy-crop` and return a Blob.
 */
export async function getCroppedImg(
  src: string,
  pixelCrop: Area,
  options: CropImageOptions = {}
): Promise<Blob | null> {
  const image = await createImage(src)
  const canvas = document.createElement("canvas")
  const ctx = canvas.getContext("2d")
  if (!ctx) return null

  const rotation = options.rotation ?? 0
  const flip = {
    horizontal: options.flip?.horizontal ?? false,
    vertical: options.flip?.vertical ?? false,
  }
  const rotRad = getRadianAngle(rotation)
  const { width: bBoxWidth, height: bBoxHeight } = rotateSize(
    image.width,
    image.height,
    rotation
  )

  canvas.width = bBoxWidth
  canvas.height = bBoxHeight

  ctx.translate(bBoxWidth / 2, bBoxHeight / 2)
  ctx.rotate(rotRad)
  ctx.scale(flip.horizontal ? -1 : 1, flip.vertical ? -1 : 1)
  ctx.translate(-image.width / 2, -image.height / 2)
  ctx.drawImage(image, 0, 0)

  const croppedCanvas = document.createElement("canvas")
  const croppedCtx = croppedCanvas.getContext("2d")
  if (!croppedCtx) return null

  croppedCanvas.width = pixelCrop.width
  croppedCanvas.height = pixelCrop.height
  croppedCtx.drawImage(
    canvas,
    pixelCrop.x,
    pixelCrop.y,
    pixelCrop.width,
    pixelCrop.height,
    0,
    0,
    pixelCrop.width,
    pixelCrop.height
  )

  const mimeType = options.mimeType ?? "image/png"
  const quality = options.quality

  return new Promise((resolve) => {
    croppedCanvas.toBlob((blob) => resolve(blob), mimeType, quality)
  })
}

/** Convenience: object URL for preview. Caller should revoke when done. */
export async function getCroppedImgUrl(
  src: string,
  pixelCrop: Area,
  options?: CropImageOptions
): Promise<string | null> {
  const blob = await getCroppedImg(src, pixelCrop, options)
  if (!blob) return null
  return URL.createObjectURL(blob)
}

export type { Area }
